/* maya-kin-engine · 玛雅历法引擎（单文件 standalone 版）
 * 与小红书小工具《玛雅天赋图腾》同源同码，双体系：
 *   A. 13月亮历 / Dreamspell（锚点 2013-07-26 = Kin 164，2月29日不占 Kin）
 *   B. 古典玛雅历法（GMT 584283 学术换算：长纪历 / Tzolk'in / Haab'）
 * 内置 23 条固化测试向量：node maya_engine.js selftest 上电自检。
 *
 * CLI（Node >= 14，零依赖）:
 *   node maya_engine.js 1990-05-15                        完整档案
 *   node maya_engine.js today                             今日 Kin
 *   node maya_engine.js match 1990-05-15 1993-08-20       双人合盘基础
 *   node maya_engine.js year 1990-05-15                   未来5年个人流年
 *   node maya_engine.js selftest                          23条向量自检
 *
 * License: MIT（引擎与名称表）。名人生日为公开资料。解读文案与品牌归作者所有。
 */
/* 银河签名 · 历法引擎
 * 体系A：13月亮历 / Dreamspell（锚点 2013-07-26 = Kin 164，2月29日不占Kin）
 * 体系B：古典玛雅历法（GMT 584283 学术换算：长纪历 / Tzolk'in / Haab'）
 * 所有公式与测试向量见 docs/01-基础研究文档.md §3
 */
(function () {
  'use strict';
  var MYA = (typeof window !== 'undefined') ? (window.MYA = window.MYA || {}) : (globalThis.MYA = globalThis.MYA || {});

  /* ---------- 基础日期工具（纯整数运算，无时区问题） ---------- */
  function isLeap(y) { return (y % 4 === 0 && y % 100 !== 0) || (y % 400 === 0); }
  function daysInMonth(y, m) { return [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]; }
  function dayNumber(y, m, d) { return Math.round(Date.UTC(y, m - 1, d) / 86400000); }

  /* ---------- 体系A：Dreamspell Kin ---------- */
  var ANCHOR_DN = dayNumber(2013, 7, 26);
  var ANCHOR_KIN = 164;

  function feb29Count(anchorDn, targetDn) {
    var count = 0;
    var lo = Math.min(anchorDn, targetDn);
    var hi = Math.max(anchorDn, targetDn);
    for (var y = 1400; y <= 2100; y++) { // 下界覆盖名人最早生年（1452），保证锚点之前的远期日期正确
      if (!isLeap(y)) continue;
      var f = dayNumber(y, 2, 29);
      if (f > lo && f <= hi) count++;
    }
    return count;
  }

  function kinOfDate(y, m, d) {
    var dn = dayNumber(y, m, d);
    var delta = dn - ANCHOR_DN;
    var backward = delta < 0;
    var skips = feb29Count(ANCHOR_DN, dn); // 区间内2月29日个数，方向无关
    var adj = backward ? delta + skips : delta - skips;
    return ((ANCHOR_KIN - 1 + adj) % 260 + 260) % 260 + 1;
  }

  function isFeb29(y, m, d) { return m === 2 && d === 29; }

  function toneOfKin(kin) { return ((kin - 1) % 13) + 1; }
  function sealOfKin(kin) { return ((kin - 1) % 20) + 1; }
  function colorOfSeal(seal) { return ['R', 'W', 'B', 'Y'][(seal - 1) % 4]; }
  function kinFromToneSeal(tone, seal) {
    // 求 Kin n 使 tone(n)=tone, seal(n)=seal（中国剩余定理，260 内唯一）
    for (var n = seal; n <= 260 + seal; n += 20) {
      if (toneOfKin(n) === tone) return ((n - 1) % 260) + 1;
    }
    return -1;
  }

  /* ---------- 第五力神谕（五大天赋印记） ---------- */
  function oracleOfKin(kin) {
    var S = sealOfKin(kin), T = toneOfKin(kin);
    var analogSeal = ((19 - S - 1) % 20 + 20) % 20 + 1;          // 支持：编号和≡19
    var antipodeSeal = ((S - 1 + 10) % 20) + 1;                   // 挑战：+10
    var occultKin = 261 - kin;                                    // 隐藏推动：Kin和=261
    var guideOffset = { 1: 0, 2: 12, 3: 4, 4: 16, 0: 8 }[T % 5];  // 引导：按T mod 5，同色
    var guideSeal = ((S - 1 + guideOffset) % 20) + 1;
    return {
      main: { kin: kin, tone: T, seal: S },
      guide: { kin: kinFromToneSeal(T, guideSeal), tone: T, seal: guideSeal },
      analog: { kin: kinFromToneSeal(T, analogSeal), tone: T, seal: analogSeal },
      antipode: { kin: kinFromToneSeal(T, antipodeSeal), tone: T, seal: antipodeSeal },
      occult: { kin: occultKin, tone: toneOfKin(occultKin), seal: sealOfKin(occultKin) }
    };
  }

  /* ---------- 波符与城堡 ---------- */
  function wavespellOfKin(kin) {
    var w = Math.floor((kin - 1) / 13);
    var start = w * 13 + 1;
    return {
      index: w + 1,
      startKin: start,
      endKin: start + 12,
      seal: sealOfKin(start),
      position: toneOfKin(kin)
    };
  }
  function castleOfKin(kin) { return Math.floor((kin - 1) / 52) + 1; }

  /* 地球家族：seal mod 5 → 0极地 1基准 2核心 3信号 4门户 */
  function earthFamilyOfSeal(seal) { return seal % 5; }
  /* 和声单元：每 4 Kin 一组，共 65 个 */
  function harmonicOfKin(kin) { return Math.floor((kin - 1) / 4) + 1; }
  /* 核心日：Tzolkin 神秘中柱的 20 天（Kin 130–149，260 的正中段） */
  function isCoreDay(kin) { return kin >= 130 && kin <= 149; }

  /* ---------- 年Kin与13月亮历日期 ---------- */
  function yearKin(year) { return kinOfDate(year, 7, 26); }

  function moonDate(y, m, d) {
    var dn = dayNumber(y, m, d);
    var startY = (dn >= dayNumber(y, 7, 26)) ? y : y - 1;
    var startDn = dayNumber(startY, 7, 26);
    var doy = dn - startDn;
    var febY = startY + 1; // 窗口内的2月属于下一个日历年
    if (isLeap(febY) && dn >= dayNumber(febY, 2, 29)) doy -= 1;
    if (doy === 364) return { outOfTime: true, moon: 13, day: 28, plasma: 7, startY: startY };
    return {
      outOfTime: false,
      moon: Math.floor(doy / 28) + 1,
      day: (doy % 28) + 1,
      plasma: ((doy % 28) % 7) + 1,
      startY: startY
    };
  }

  /* 个人流年：生日当天Kin每年 +105（365 mod 260），直接用生日计算恒等成立 */
  function personalYearKin(birthY, birthM, birthD, targetY) {
    var d = Math.min(birthD, daysInMonth(targetY, birthM));
    return kinOfDate(targetY, birthM, d);
  }

  /* ---------- 体系B：古典玛雅历（GMT 584283） ---------- */
  var TZOLKIN_NAMES = ["Imix'", "Ik'", "Ak'b'al", "K'an", "Chikchan", "Kimi", "Manik'", "Lamat", "Muluk", "Ok", "Chuwen", "Eb'", "B'en", "Ix", "Men", "K'ib'", "Kab'an", "Etz'nab'", "Kawak", "Ajaw"];
  var HAAB_MONTHS = ["Pop", "Wo'", "Sip", "Sotz'", "Sek", "Xul", "Yaxk'in", "Mol", "Ch'en", "Yax", "Sak'", "Keh", "Mak", "K'ank'in", "Muwan", "Pax", "K'ayab", "Kumk'u", "Wayeb'"];

  function jdn(y, m, d) {
    var a = Math.floor((14 - m) / 12);
    var y2 = y + 4800 - a;
    var m2 = m + 12 * a - 3;
    return d + Math.floor((153 * m2 + 2) / 5) + 365 * y2 + Math.floor(y2 / 4) - Math.floor(y2 / 100) + Math.floor(y2 / 400) - 32045;
  }

  function classicMaya(y, m, d) {
    var j = jdn(y, m, d);
    var days = j - 584283;
    var baktun = Math.floor(days / 144000); days -= baktun * 144000;
    var katun = Math.floor(days / 7200); days -= katun * 7200;
    var tun = Math.floor(days / 360); days -= tun * 360;
    var uinal = Math.floor(days / 20);
    var kin = days - uinal * 20;
    var tzNum = ((j + 5) % 13) + 1;
    var tzName = TZOLKIN_NAMES[(j + 16) % 20];
    var haabIdx = (j + 65) % 365; // 0 起始日约定（"0 Pop"为就座日）
    var haabDay = haabIdx % 20;
    var haabMonth = HAAB_MONTHS[Math.floor(haabIdx / 20)];
    return {
      longCount: baktun + '.' + katun + '.' + tun + '.' + uinal + '.' + kin,
      tzolkinNumber: tzNum,
      tzolkinName: tzName,
      haab: haabDay + ' ' + haabMonth,
      haabDay: haabDay,
      haabMonth: haabMonth
    };
  }

  /* ---------- 体系B扩展：传统命理组件（trecena 旬 / Katun 时代） ---------- */
  /* trecena：出生日所在的 13 日旬，以旬首（数字1那天）的日名命名 */
  function trecenaOf(y, m, d) {
    var c = classicMaya(y, m, d);
    var nameIdx = TZOLKIN_NAMES.indexOf(c.tzolkinName) + 1;
    var startIdx = ((nameIdx - 1 - (c.tzolkinNumber - 1)) % 20 + 20) % 20 + 1;
    return { nameIdx: startIdx, position: c.tzolkinNumber, name: TZOLKIN_NAMES[startIdx - 1] };
  }
  /* Katun：约 19.7 年的时代单位，传统以其结束日的 Ajaw 名命名（Chilam Balam 惯例） */
  function jdnToIso(j) {
    var dt = new Date((j - 2440588) * 86400000);
    return dt.getUTCFullYear() + '.' + (dt.getUTCMonth() + 1) + '.' + dt.getUTCDate();
  }
  function katunOf(y, m, d) {
    var j = jdn(y, m, d);
    var n = Math.floor((j - 584283) / 7200);
    var startJ = 584283 + n * 7200, endJ = startJ + 7200;
    return {
      name: (((endJ + 5) % 13) + 1) + ' ' + TZOLKIN_NAMES[(endJ + 16) % 20],
      start: jdnToIso(startJ), end: jdnToIso(endJ - 1)
    };
  }

  /* ---------- 引擎自检（固化测试向量，上电必须全过） ---------- */
  var TESTS = [
    ['kin', [1939, 1, 24], 11], ['kin', [1997, 7, 26], 44], ['kin', [2000, 1, 1], 153],
    ['kin', [2012, 7, 26], 59], ['kin', [2012, 12, 21], 207], ['kin', [2013, 7, 26], 164],
    ['kin', [2014, 7, 26], 9], ['kin', [2018, 2, 8], 1], ['kin', [2019, 7, 26], 14],
    ['kin', [2024, 7, 26], 19], ['kin', [2026, 7, 26], 229],
    ['oracle1', 1, null], ['oracle11', 11, null], ['oracle81', 81, null],
    ['lc', [2000, 1, 1], '12.19.6.15.2'], ['lc', [2012, 12, 21], '13.0.0.0.0'], ['lc', [2026, 7, 26], '13.0.13.14.5'],
    ['tz', [2012, 12, 21], '4 Ajaw'], ['tz', [2000, 1, 1], "11 Ik'"],
    ['haab', [2012, 12, 21], "3 K'ank'in"], ['haab', [2000, 1, 1], "10 K'ank'in"], ['haab', [2026, 7, 26], '18 Xul'],
    ['trecena', [2012, 12, 21], "Kab'an|4"], ['trecena', [2000, 1, 1], "Eb'|11"],
    ['katun', [2012, 12, 21], '2 Ajaw'], ['katun', [2026, 8, 21], '2 Ajaw'], ['katun', [1990, 5, 12], '6 Ajaw'], ['katun', [1950, 3, 8], '10 Ajaw'],
    ['wave', 254, 20]
  ];

  function runSelfTest() {
    var fails = [];
    for (var i = 0; i < TESTS.length; i++) {
      var t = TESTS[i], kind = t[0], a = t[1], expect = t[2], got;
      if (kind === 'kin') got = kinOfDate(a[0], a[1], a[2]);
      else if (kind === 'oracle1') {
        var o = oracleOfKin(1);
        got = (o.analog.kin === 118 && o.antipode.kin === 131 && o.occult.kin === 260 && o.guide.kin === 1) ? 'ok' : 'bad:' + JSON.stringify(o);
        expect = 'ok';
      } else if (kind === 'oracle11') {
        var o11 = oracleOfKin(11); // Kin11 蓝光谱猴(S=11,T=11)
        got = (o11.analog.kin === 128 && o11.antipode.kin === 141 && o11.occult.kin === 250 && o11.guide.kin === 11) ? 'ok' : 'bad';
        expect = 'ok';
      } else if (kind === 'oracle81') {
        var o81 = oracleOfKin(81); // Kin81 红电力龙(S=1,T=3)
        got = (o81.analog.kin === 198 && o81.antipode.kin === 211 && o81.occult.kin === 180 && o81.guide.seal === 5) ? 'ok' : 'bad';
        expect = 'ok';
      } else if (kind === 'lc') got = classicMaya(a[0], a[1], a[2]).longCount;
      else if (kind === 'tz') { var c = classicMaya(a[0], a[1], a[2]); got = c.tzolkinNumber + ' ' + c.tzolkinName; }
      else if (kind === 'haab') got = classicMaya(a[0], a[1], a[2]).haab;
      else if (kind === 'trecena') { var tr = trecenaOf(a[0], a[1], a[2]); got = tr.name + '|' + tr.position; }
      else if (kind === 'katun') got = katunOf(a[0], a[1], a[2]).name;
      else if (kind === 'wave') got = wavespellOfKin(a).index === expect && wavespellOfKin(a).seal === 8 ? 20 : -1;
      if (got !== expect) fails.push(kind + ' ' + JSON.stringify(a) + ' expect=' + expect + ' got=' + got);
    }
    return { pass: fails.length === 0, fails: fails };
  }

  MYA.engine = {
    isLeap: isLeap, daysInMonth: daysInMonth, dayNumber: dayNumber,
    kinOfDate: kinOfDate, isFeb29: isFeb29,
    toneOfKin: toneOfKin, sealOfKin: sealOfKin, colorOfSeal: colorOfSeal, kinFromToneSeal: kinFromToneSeal,
    oracleOfKin: oracleOfKin, wavespellOfKin: wavespellOfKin, castleOfKin: castleOfKin,
    earthFamilyOfSeal: earthFamilyOfSeal, harmonicOfKin: harmonicOfKin, isCoreDay: isCoreDay,
    yearKin: yearKin, moonDate: moonDate, personalYearKin: personalYearKin,
    classicMaya: classicMaya, TZOLKIN_NAMES: TZOLKIN_NAMES, trecenaOf: trecenaOf, katunOf: katunOf,
    runSelfTest: runSelfTest
  };
})();


